-- "Rol": async tabletop RPG campaigns (simple or advanced rules; human, AI-assisted or AI narrator). Run once. (No comments below this line, so pasting into the D1 console works.)
CREATE TABLE IF NOT EXISTS rpg_campaigns ( id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, setting TEXT, rules TEXT NOT NULL DEFAULT 'simple', dm_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, dm_mode TEXT NOT NULL DEFAULT 'human', status TEXT NOT NULL DEFAULT 'recruiting', turn_hours INTEGER NOT NULL DEFAULT 24, max_players INTEGER NOT NULL DEFAULT 6, lang TEXT NOT NULL DEFAULT 'es', summary TEXT, resolving INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS rpg_characters ( id INTEGER PRIMARY KEY AUTOINCREMENT, campaign_id INTEGER NOT NULL REFERENCES rpg_campaigns(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, icon TEXT, concept TEXT, class TEXT, stats TEXT NOT NULL, xp INTEGER NOT NULL DEFAULT 0, hp INTEGER NOT NULL, max_hp INTEGER NOT NULL, ac INTEGER NOT NULL, gold INTEGER NOT NULL DEFAULT 10, inventory TEXT NOT NULL DEFAULT '[]', notes TEXT, created_at INTEGER NOT NULL, UNIQUE (campaign_id, user_id) );
CREATE TABLE IF NOT EXISTS rpg_scenes ( id INTEGER PRIMARY KEY AUTOINCREMENT, campaign_id INTEGER NOT NULL REFERENCES rpg_campaigns(id) ON DELETE CASCADE, num INTEGER NOT NULL, narration TEXT NOT NULL, author TEXT NOT NULL DEFAULT 'dm', effects TEXT, status TEXT NOT NULL DEFAULT 'open', opened_at INTEGER NOT NULL, deadline INTEGER NOT NULL, reminded INTEGER NOT NULL DEFAULT 0, dm_pinged INTEGER NOT NULL DEFAULT 0 );
CREATE INDEX IF NOT EXISTS rpg_scenes_campaign ON rpg_scenes (campaign_id, num);
CREATE TABLE IF NOT EXISTS rpg_actions ( id INTEGER PRIMARY KEY AUTOINCREMENT, scene_id INTEGER NOT NULL REFERENCES rpg_scenes(id) ON DELETE CASCADE, character_id INTEGER NOT NULL REFERENCES rpg_characters(id) ON DELETE CASCADE, text TEXT NOT NULL, rolls TEXT NOT NULL DEFAULT '[]', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE (scene_id, character_id) );
